from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
# Try to find any synced tables in any schema
# Look in schemas that match existing lakebase projects
for schema_name in ['mlpab17de0a', 'mlpabbfc2a9', 'mlpabf82a62']:
    try:
        tables = list(w.tables.list(catalog_name='workspace', schema_name=schema_name))
        for t in tables:
            print(f'{schema_name}.{t.name}: {t.table_type}')
    except Exception as e:
        print(f'{schema_name}: Error: {e}')
